(function(){
'use strict';
var STATE_KEY='welog-pair-sheet-v4';
function readState(){try{return JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}}catch(e){return{}}}
async function waitReady(sheet){if(document.fonts){try{await document.fonts.ready}catch(e){}}var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})}
function hideEditorOverlays(sheet){var list=[].slice.call(sheet.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate,.st-v2-lock,.st-v2-del,.st-v2-resize,.direct-crop-ui,.guide-line'));var prev=list.map(function(el){return{el:el,visibility:el.style.visibility}});list.forEach(function(el){el.style.setProperty('visibility','hidden','important')});return function(){prev.forEach(function(x){x.el.style.visibility=x.visibility})}}
function expandForFullContent(sheet){var prev={height:sheet.style.height,minHeight:sheet.style.minHeight,maxHeight:sheet.style.maxHeight,overflow:sheet.style.overflow,overflowY:sheet.style.overflowY};var grid=sheet.querySelector('.sheet-grid');var gridPrev=grid?{height:grid.style.height,minHeight:grid.style.minHeight,maxHeight:grid.style.maxHeight,overflow:grid.style.overflow,overflowY:grid.style.overflowY}:null;sheet.style.setProperty('height','auto','important');sheet.style.setProperty('max-height','none','important');sheet.style.setProperty('overflow','visible','important');sheet.style.setProperty('overflow-y','visible','important');if(grid){grid.style.setProperty('height','auto','important');grid.style.setProperty('max-height','none','important');grid.style.setProperty('overflow','visible','important');grid.style.setProperty('overflow-y','visible','important')}var contentBottom=sheet.getBoundingClientRect().top;sheet.querySelectorAll('*').forEach(function(el){var r=el.getBoundingClientRect();if(r.bottom>contentBottom)contentBottom=r.bottom});var sr=sheet.getBoundingClientRect(),needed=Math.max(sheet.scrollHeight,Math.ceil(contentBottom-sr.top));sheet.style.setProperty('min-height',needed+'px','important');sheet.style.setProperty('height',needed+'px','important');return function(){sheet.style.height=prev.height;sheet.style.minHeight=prev.minHeight;sheet.style.maxHeight=prev.maxHeight;sheet.style.overflow=prev.overflow;sheet.style.overflowY=prev.overflowY;if(grid&&gridPrev){grid.style.height=gridPrev.height;grid.style.minHeight=gridPrev.minHeight;grid.style.maxHeight=gridPrev.maxHeight;grid.style.overflow=gridPrev.overflow;grid.style.overflowY=gridPrev.overflowY}}}
function downloadBlob(blob,name){var u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name+'.png';document.body.appendChild(a);a.click();setTimeout(function(){a.remove();URL.revokeObjectURL(u)},1500)}
async function canvasBlob(canvas){return await new Promise(function(res,rej){try{canvas.toBlob(function(b){b?res(b):rej(new Error('PNG blob creation failed'))},'image/png')}catch(e){rej(e)}})}
async function captureHtml2Canvas(sheet){if(!window.html2canvas)throw new Error('html2canvas unavailable');var r=sheet.getBoundingClientRect(),w=Math.ceil(r.width),h=Math.ceil(Math.max(r.height,sheet.scrollHeight));return await window.html2canvas(sheet,{scale:Math.max(2,window.devicePixelRatio||1),useCORS:true,allowTaint:false,backgroundColor:null,logging:false,imageTimeout:30000,foreignObjectRendering:false,removeContainer:true,width:w,height:h})}
async function captureHtmlToImage(sheet){if(!window.htmlToImage||!window.htmlToImage.toPng)throw new Error('html-to-image unavailable');var r=sheet.getBoundingClientRect(),w=Math.ceil(r.width),h=Math.ceil(Math.max(r.height,sheet.scrollHeight));var url=await window.htmlToImage.toPng(sheet,{pixelRatio:Math.max(2,window.devicePixelRatio||1),cacheBust:true,backgroundColor:null,skipAutoScale:false,width:w,height:h,style:{width:w+'px',height:h+'px',maxHeight:'none',overflow:'visible'}});var resp=await fetch(url);if(!resp.ok)throw new Error('fallback image conversion failed');return await resp.blob()}
async function saveLive(){var sheet=document.getElementById('sheet'),btn=document.getElementById('printBtn');if(!sheet||!btn)return;var old=btn.textContent,restoreOverlay=function(){},restoreSize=function(){};btn.disabled=true;btn.textContent='저장 중…';try{
  await waitReady(sheet);
  restoreOverlay=hideEditorOverlays(sheet);
  restoreSize=expandForFullContent(sheet);
  await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});
  var blob;
  try{var canvas=await captureHtml2Canvas(sheet);blob=await canvasBlob(canvas)}catch(firstError){console.warn('html2canvas live capture failed; trying fallback',firstError);blob=await captureHtmlToImage(sheet)}
  var name=((readState().pairName||'WeLog').trim()||'WeLog');downloadBlob(blob,name);
}catch(e){console.error('live sheet save failed',e);alert('PNG 저장에 실패했습니다. 다시 시도해 주세요.')}finally{try{restoreSize()}catch(e){}try{restoreOverlay()}catch(e){}btn.disabled=false;btn.textContent=old}}
function install(){var old=document.getElementById('printBtn');if(!old)return;var b=old.cloneNode(true);b.dataset.liveSaveReady='4';old.replaceWith(b);b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();saveLive()},true)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install);else install();setTimeout(install,500);
})();